import { useEffect, useState } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
} from "recharts";

const COLORS = ["#22c55e", "#84cc16", "#facc15", "#f97316", "#ef4444"];

export default function Reviews() {
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        const res = await fetch(
          "http://localhost:5001/admin/reviews/analytics"
        );
        if (!res.ok) throw new Error("Failed to fetch analytics");
        const data = await res.json();
        setAnalytics(data);
      } catch (err) {
        setError("Unable to load review analytics");
      } finally {
        setLoading(false);
      }
    };

    fetchAnalytics();
  }, []);

  if (loading)
    return <div className="p-10 text-gray-400">Loading insights…</div>;

  if (error)
    return <div className="p-10 text-red-400">{error}</div>;

  const ratingData = Object.entries(
    analytics.ratingDistribution
  ).map(([rating, count]) => ({
    rating: `${rating}★`,
    count,
  }));

  const pieData = ratingData.map((r) => ({
    name: r.rating,
    value: r.count,
  }));

  return (
    <div className="p-10 text-white">
      {/* HEADER */}
      <h1 className="text-4xl font-bold text-yellow-400 mb-4">
        Customer Voice Intelligence
      </h1>
      <p className="text-gray-400 max-w-4xl mb-12">
        Auto-moderated reviews reflect real customer sentiment.
        This dashboard transforms raw feedback into strategic insight.
      </p>

      {/* KPI GRID */}
      <div className="grid md:grid-cols-4 gap-6 mb-16">
        <InsightCard
          title="Average Rating"
          value={`${analytics.avgRating.toFixed(1)} ★`}
          desc="Overall satisfaction score"
        />
        <InsightCard
          title="Total Reviews"
          value={analytics.totalReviews}
          desc="Authentic user feedback"
        />
        <InsightCard
          title="Negative Signals"
          value={analytics.flaggedReviews}
          desc="Complaints & low ratings"
          danger
        />
        <InsightCard
          title="Customer Loyalty (NPS)"
          value={`${analytics.nps}%`}
          desc="Referral likelihood"
        />
      </div>

      {/* CHARTS */}
      <div className="grid md:grid-cols-2 gap-10 mb-16">
        {/* BAR CHART */}
        <ChartPanel title="Rating Distribution">
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={ratingData}>
              <XAxis dataKey="rating" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="count">
                {ratingData.map((_, i) => (
                  <Cell key={i} fill={COLORS[i]} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </ChartPanel>

        {/* PIE CHART */}
        <ChartPanel title="Sentiment Share">
          <ResponsiveContainer width="100%" height={280}>
            <PieChart>
              <Pie
                data={pieData}
                dataKey="value"
                nameKey="name"
                outerRadius={100}
                label
              >
                {pieData.map((_, i) => (
                  <Cell key={i} fill={COLORS[i]} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </ChartPanel>
      </div>

      {/* INTERPRETATION */}
      <div className="grid md:grid-cols-2 gap-8">
        <InsightPanel title="Customer Emotion">
          {analytics.avgRating >= 4 ? (
            <p className="text-green-400">
              Strong trust and satisfaction. Brand perception is
              highly positive.
            </p>
          ) : analytics.avgRating >= 3 ? (
            <p className="text-yellow-400">
              Mixed sentiment. Improve consistency and experience.
            </p>
          ) : (
            <p className="text-red-400">
              High dissatisfaction detected. Immediate improvements
              required.
            </p>
          )}
        </InsightPanel>

        <InsightPanel title="Strategic Focus Areas">
          <ul className="list-disc ml-5 text-gray-300 space-y-2">
            <li>Service quality & staff engagement</li>
            <li>Pricing clarity & membership value</li>
            <li>Facilities, hygiene & crowd management</li>
            <li>User onboarding experience</li>
          </ul>
        </InsightPanel>
      </div>

      {/* FOOTER */}
      <div className="mt-16 text-sm text-gray-500 max-w-4xl">
        Reviews are automatically filtered using safety rules.
        Low-quality or abusive content is excluded from analytics.
        Admins focus only on insight — not moderation.
      </div>
    </div>
  );
}

/* ================= COMPONENTS ================= */

function InsightCard({ title, value, desc, danger }) {
  return (
    <div
      className={`bg-gradient-to-br from-[#0b0b0b] to-[#111]
      border ${danger ? "border-red-500/40" : "border-yellow-500/30"}
      rounded-3xl p-8 shadow-xl`}
    >
      <p className="text-gray-400 text-sm">{title}</p>
      <p
        className={`text-4xl font-bold mt-4 ${
          danger ? "text-red-400" : "text-yellow-400"
        }`}
      >
        {value}
      </p>
      <p className="text-gray-500 text-sm mt-3">{desc}</p>
    </div>
  );
}

function ChartPanel({ title, children }) {
  return (
    <div className="bg-gradient-to-br from-[#0b0b0b] to-[#111]
      border border-yellow-500/30 rounded-3xl p-8 shadow-xl">
      <h2 className="text-xl font-semibold text-yellow-400 mb-6">
        {title}
      </h2>
      {children}
    </div>
  );
}

function InsightPanel({ title, children }) {
  return (
    <div className="bg-gradient-to-br from-[#0b0b0b] to-[#111]
      border border-yellow-500/30 rounded-3xl p-8 shadow-xl">
      <h2 className="text-xl font-semibold text-yellow-400 mb-4">
        {title}
      </h2>
      {children}
    </div>
  );
}
